const logoSrc = `data:image/svg+xml;utf8,${encodeURIComponent(logoSvg)}`;

const palettes = {
  dark: {
    background: '#0D0A1A',
    backgroundMid: '#17112B',
    backgroundEnd: '#241A3F',
    surface: '#120E20',
    text: '#FDFCFF',
    textMuted: '#C9C1D9',
    textSubtle: '#9E93B4',
    primary: '#A78BFA',
    primaryStrong: '#775FFF',
    secondaryBlob: '#123E61',
    badgeBg: 'rgba(38, 32, 56, 0.86)',
    borderStrong: 'rgba(228, 221, 244, 0.18)',
  },
  light: {
    background: '#FDFCFF',
    backgroundMid: '#F3EFFF',
    backgroundEnd: '#EAF8FF',
    surface: '#FFFFFF',
    text: '#171126',
    textMuted: '#5C526F',
    textSubtle: '#817694',
    primary: '#5B3DFF',
    primaryStrong: '#775FFF',
    secondaryBlob: '#BDEFFF',
    badgeBg: 'rgba(238, 232, 255, 0.9)',
    borderStrong: 'rgba(91, 61, 255, 0.18)',
  },
} as const;

type OgTheme = keyof typeof palettes;

export function createOpenGraphImage(theme: OgTheme = 'dark') {
  const palette = palettes[theme];
  const badgeStyle = {
    display: 'flex',
    alignItems: 'center',
    padding: '10px 16px',
    color: palette.textMuted,
    background: palette.badgeBg,
    border: `1px solid ${palette.borderStrong}`,
    borderRadius: 999,
    fontSize: 18,
    fontWeight: 650,
  } as const;

  return new ImageResponse(
    <div
      style={{
        position: 'relative',
        display: 'flex',
        width: '100%',
        height: '100%',
        overflow: 'hidden',
        color: palette.text,
        background: `linear-gradient(135deg, ${palette.background} 0%, ${palette.backgroundMid} 56%, ${palette.backgroundEnd} 100%)`,
        fontFamily: 'Vellira Sans, Inter, ui-sans-serif, system-ui, sans-serif',
      }}
    >
      <div
        style={{
          position: 'absolute',
          top: -240,
          left: -180,
          width: 640,
          height: 640,
          background: palette.primaryStrong,
          borderRadius: 999,
          opacity: theme === 'dark' ? 0.26 : 0.1,
        }}
      />

      <div
        style={{
          position: 'absolute',
          right: -260,
          bottom: -320,
          width: 760,
          height: 760,
          background: palette.secondaryBlob,
          borderRadius: 999,
          opacity: theme === 'dark' ? 0.46 : 0.7,
        }}
      />

      <div
        style={{
          position: 'absolute',
          inset: 36,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
          padding: '58px 64px',
          background: palette.surface,
          border: `1px solid ${palette.borderStrong}`,
          borderRadius: 32,
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <img
            src={logoSrc}
            width={190}
            height={52}
            alt='Vellira'
            style={{ objectFit: 'contain' }}
          />

          <div
            style={{
              display: 'flex',
              color: palette.textSubtle,
              fontSize: 20,
              fontWeight: 700,
            }}
          >
            vellira.dev
          </div>
        </div>

        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            maxWidth: 1000,
          }}
        >
          <div
            style={{
              display: 'flex',
              marginBottom: 24,
              color: palette.primary,
              fontSize: 24,
              fontWeight: 700,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
            }}
          >
            React · React Native · Design tokens
          </div>

          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              fontSize: 82,
              fontWeight: 800,
              lineHeight: 1.02,
              letterSpacing: 0,
            }}
          >
            <span>Independent modules.</span>

            <span
              style={{
                display: 'flex',
                marginTop: 8,
                color: palette.primary,
              }}
            >
              One seamless system.
            </span>
          </div>

          <div
            style={{
              display: 'flex',
              maxWidth: 900,
              marginTop: 32,
              color: palette.textMuted,
              fontSize: 27,
              lineHeight: 1.4,
            }}
          >
            Cross-platform components with shared APIs, accessible behaviour and
            semantic design tokens.
          </div>
        </div>

        <div
          style={{
            display: 'flex',
            gap: 12,
          }}
        >
          <span style={badgeStyle}>Accessible</span>
          <span style={badgeStyle}>Type-safe</span>
          <span style={badgeStyle}>Themeable</span>
        </div>
      </div>
    </div>,
    size
  );
}

export default function OpenGraphImage() {
  return createOpenGraphImage('dark');
}
